using System.Collections.Generic;using Alterverse.Combat;using Alterverse.Match;using Alterverse.Visuals;using UnityEngine;using UnityEngine.InputSystem;
namespace Alterverse.Characters
{
[RequireComponent(typeof(Health),typeof(HeroIdentity),typeof(HeroAbilityKit))]public sealed class PlayerHeroAbilities:MonoBehaviour
{
private readonly Collider[] hitBuffer=new Collider[40];private Health self;private HeroIdentity identity;private HeroAbilityKit kit;private HeroCombatProfile profile;private TeamMember team;private PlanetBuffReceiver planetBuff;private float qReady,wReady,eReady,ultReady;public float QRemaining=>Mathf.Max(0,qReady-Time.time);public float WRemaining=>Mathf.Max(0,wReady-Time.time);public float ERemaining=>Mathf.Max(0,eReady-Time.time);public float UltRemaining=>Mathf.Max(0,ultReady-Time.time);public string QName=>kit!=null?kit.Q.Name:"Q";public string WName=>kit!=null?kit.W.Name:"W";public string EName=>kit!=null?kit.E.Name:"E";public string UltName=>kit!=null?kit.Ultimate.Name:"ULT";private float Cooldown(float value)=>value*(planetBuff!=null?planetBuff.CooldownMultiplier:1f);
private void Awake(){Refresh();}public void Refresh(){self=GetComponent<Health>();identity=GetComponent<HeroIdentity>();kit=GetComponent<HeroAbilityKit>();profile=GetComponent<HeroCombatProfile>();team=GetComponent<TeamMember>();planetBuff=GetComponent<PlanetBuffReceiver>();}private void Update(){if(planetBuff==null)planetBuff=GetComponent<PlanetBuffReceiver>();if(!CanAct||Keyboard.current==null)return;if(Keyboard.current.qKey.wasPressedThisFrame)CastQ();if(Keyboard.current.eKey.wasPressedThisFrame)CastW();if(Keyboard.current.rKey.wasPressedThisFrame)CastE();if(Keyboard.current.fKey.wasPressedThisFrame)CastUltimate();}
private bool CanAct=>self!=null&&!self.IsDead&&identity!=null&&kit!=null;public bool CastQ()=>TryCast(kit.Q,ref qReady,0);public bool CastW()=>TryCast(kit.W,ref wReady,1);public bool CastE()=>TryCast(kit.E,ref eReady,2);public bool CastUltimate()=>TryCast(kit.Ultimate,ref ultReady,3);
private bool TryCast(AbilitySpec spec,ref float ready,int slot){if(!CanAct||Time.time<ready)return false;Health target=FindNearestEnemy(spec.Range);Color accent=StylizedArtDirection.HeroAccent(identity.Hero);if(identity.Hero==HeroId.Mira&&slot!=0){ready=Time.time+Cooldown(spec.Cooldown);float amount=spec.Power>0?spec.Power*(profile!=null?profile.AbilityPower:1f):self.Max*(slot==3?.22f:.12f);Health healed=HealWeakestAlly(amount);PrototypeVfx.Ring(healed!=null?healed.transform.position:transform.position,accent,slot==3?2.4f:1.5f,.4f);return true;}if((identity.Hero==HeroId.Kaelon||identity.Hero==HeroId.Rook)&&slot==1){ready=Time.time+Cooldown(spec.Cooldown);self.Heal(self.Max*(identity.Hero==HeroId.Kaelon?.12f:.09f));PrototypeVfx.Ring(transform.position,accent,identity.Hero==HeroId.Kaelon?2.2f:1.6f,.32f);return true;}if(identity.Hero==HeroId.Nyra&&slot==1){ready=Time.time+Cooldown(spec.Cooldown);Vector3 from=transform.position;Reposition(target,3);PrototypeVfx.ShadowTrail(from,transform.position,accent);return true;}if(identity.Hero==HeroId.Elyra&&slot==2){ready=Time.time+Cooldown(spec.Cooldown);Vector3 from=transform.position;Reposition(target,2);PrototypeVfx.Ring(from,accent,1.4f,.25f);PrototypeVfx.Ring(transform.position,accent,1.4f,.25f);return true;}if(identity.Hero==HeroId.Veyr&&slot==2){ready=Time.time+Cooldown(spec.Cooldown);Vector3 from=transform.position;Reposition(target,4.2f);PrototypeVfx.ShadowTrail(from,transform.position,accent);return true;}if(target==null)return false;ready=Time.time+Cooldown(spec.Cooldown);float damage=spec.Power*(profile!=null?profile.AbilityPower:1f);if(damage<=0)return true;if(identity.Hero==HeroId.Veyr&&slot==3)damage*=1+(1-target.Normalized)*.55f;target.TakeDamage(damage,gameObject);PrototypeVfx.Slash(transform,accent,slot==3?2.5f:1.6f);PrototypeVfx.Burst(target.transform.position,accent,slot==3?1.35f:.85f,slot==3?10:6);if(slot==3)PrototypeVfx.Ring(target.transform.position,accent,2.1f,.38f);if(identity.Hero==HeroId.Veyr)self.Heal(damage*.12f);if(identity.Hero==HeroId.Rook&&self.Normalized<.45f)self.Heal(damage*.1f);return true;}
private Health FindNearestEnemy(float radius){int count=Physics.OverlapSphereNonAlloc(transform.position,Mathf.Max(1,radius),hitBuffer,~0,QueryTriggerInteraction.Ignore);Health best=null;float sq=float.MaxValue;HashSet<Health> seen=new();for(int i=0;i<count;i++){Collider hit=hitBuffer[i];if(hit==null)continue;Health h=hit.GetComponentInParent<Health>();if(h==null||!seen.Add(h)||h==self||h.IsDead)continue;TeamMember tm=h.GetComponent<TeamMember>();if(tm==null||team==null||tm.Team==team.Team)continue;float d=(h.transform.position-transform.position).sqrMagnitude;if(d<sq){sq=d;best=h;}}return best;}
private Health HealWeakestAlly(float amount){Health[] all=FindObjectsByType<Health>(FindObjectsSortMode.None);Health best=self;float lowest=self.Normalized;foreach(Health h in all){if(h==null||h.IsDead)continue;TeamMember tm=h.GetComponent<TeamMember>();if(tm!=null&&team!=null&&tm.Team==team.Team&&h.Normalized<lowest){lowest=h.Normalized;best=h;}}best.Heal(Mathf.Max(1,amount));return best;}
private void Reposition(Health target,float distance){Vector3 direction=target!=null?transform.position-target.transform.position:transform.forward;if(identity!=null&&identity.Hero==HeroId.Veyr&&target!=null)direction=target.transform.position-transform.position;if(direction.sqrMagnitude<.01f)direction=transform.forward;direction.y=0;Vector3 p=transform.position+direction.normalized*distance;p.x=Mathf.Clamp(p.x,-41,41);p.z=Mathf.Clamp(p.z,-35,35);CharacterController cc=GetComponent<CharacterController>();if(cc!=null&&cc.enabled){cc.enabled=false;transform.position=p;cc.enabled=true;}else transform.position=p;}
}
}
